const config = $('Configure alert intelligence workflow').first().json;
const now = new Date();
let from = new Date(now);

if (config.runMode === 'immediate') from.setMinutes(from.getMinutes() - config.immediateLookbackMinutes);
else if (config.runMode === 'weekly') from.setDate(from.getDate() - 7);
else if (config.runMode === 'monthly' || config.runMode === 'manual_report') from.setDate(from.getDate() - 30);
else if (config.runMode === 'immediate_test') from.setDate(from.getDate() - config.manualTestLookbackDays);

const threatDetection = {
  bool: {
    should: [
      { exists: { field: 'rule.mitre.tactic' } },
      { exists: { field: 'rule.mitre.technique' } },
    ],
    minimum_should_match: 1,
  },
};
const fileIntegrity = {
  bool: {
    should: [
      { term: { 'rule.groups': 'syscheck' } },
      { term: { 'rule.groups': 'fim' } },
    ],
    minimum_should_match: 1,
  },
};
const configurationAssessment = { term: { 'rule.groups': 'sca' } };
const vulnerabilityDetection = { term: { 'rule.groups': 'vulnerability-detector' } };
const authentication = {
  bool: {
    should: [
      { term: { 'rule.groups': 'authentication_success' } },
      { term: { 'rule.groups': 'authentication_failed' } },
      { term: { 'rule.groups': 'authentication_failures' } },
      { term: { 'rule.groups': 'pam' } },
      { term: { 'rule.groups': 'sshd' } },
    ],
    minimum_should_match: 1,
  },
};
const operational = {
  bool: {
    should: [
      { term: { 'rule.groups': 'ossec' } },
      { term: { 'rule.groups': 'docker' } },
      { term: { 'rule.groups': 'rootcheck' } },
      { term: { 'rule.groups': 'agentless' } },
    ],
    minimum_should_match: 1,
  },
};
const compliance = {
  bool: {
    should: [
      { exists: { field: 'rule.pci_dss' } },
      { exists: { field: 'rule.hipaa' } },
      { exists: { field: 'rule.gdpr' } },
      { exists: { field: 'rule.nist_800_53' } },
      { exists: { field: 'rule.tsc' } },
      { exists: { field: 'rule.cis' } },
      { exists: { field: 'rule.soc_2' } },
    ],
    minimum_should_match: 1,
  },
};
const recognizedContext = {
  bool: {
    should: [
      threatDetection,
      fileIntegrity,
      configurationAssessment,
      vulnerabilityDetection,
      authentication,
      operational,
      compliance,
    ],
    minimum_should_match: 1,
  },
};

return [{
  json: {
    runMode: config.runMode,
    periodStart: from.toISOString(),
    periodEnd: now.toISOString(),
    query: {
      size: config.technicalEvidenceLimit,
      track_total_hits: true,
      query: ['immediate', 'immediate_test'].includes(config.runMode)
        ? {
            bool: {
              filter: [
                { range: { timestamp: { gte: from.toISOString(), lte: now.toISOString() } } },
                { range: { 'rule.level': { gte: config.highLevelMin } } },
              ],
            },
          }
        : { range: { timestamp: { gte: from.toISOString(), lte: now.toISOString() } } },
      sort: [{ timestamp: { order: 'desc', unmapped_type: 'date' } }],
      aggs: {
        by_level: { terms: { field: 'rule.level', size: 20 } },
        top_rules: {
          terms: { field: 'rule.id', size: 25 },
          aggs: {
            sample: {
              top_hits: {
                size: 1,
                _source: ['timestamp', 'rule', 'agent', 'data', 'decoder', 'location'],
              },
            },
          },
        },
        top_agents: { terms: { field: 'agent.name', size: 15, missing: 'unassigned' } },
        use_case_coverage: {
          filters: {
            filters: {
              threat_detection: threatDetection,
              file_integrity_monitoring: fileIntegrity,
              security_configuration_assessment: configurationAssessment,
              vulnerability_detection: vulnerabilityDetection,
              authentication_monitoring: authentication,
              system_operational_monitoring: operational,
              compliance_context: compliance,
              other_unclassified: { bool: { must_not: [recognizedContext] } },
            },
          },
        },
        threat_mitre: {
          filter: threatDetection,
          aggs: {
            tactics: { terms: { field: 'rule.mitre.tactic', size: 15 } },
            techniques: { terms: { field: 'rule.mitre.technique', size: 15 } },
          },
        },
        event_trend: {
          date_histogram: {
            field: 'timestamp',
            fixed_interval: ['immediate', 'immediate_test'].includes(config.runMode) ? '1m' : '1d',
            min_doc_count: 0,
          },
        },
      },
    },
  },
}];

const response = $input.first().json;
const config = $('Configure alert intelligence workflow').first().json;
const queryMeta = $('Prepare bounded Wazuh alert query').first().json;
const hits = response.hits?.hits || [];
const total = Number(response.hits?.total?.value ?? response.hits?.total ?? hits.length);
const aggs = response.aggregations || {};
const severityBuckets = aggs.by_level?.buckets || [];

const countRange = (min, max = Infinity) => severityBuckets
  .filter((bucket) => Number(bucket.key) >= min && Number(bucket.key) <= max)
  .reduce((sum, bucket) => sum + Number(bucket.doc_count || 0), 0);

const counts = {
  critical: countRange(config.criticalLevelMin),
  high: countRange(config.highLevelMin, config.criticalLevelMin - 1),
  medium: countRange(config.mediumLevelMin, config.highLevelMin - 1),
  low: countRange(config.lowLevelMin, config.mediumLevelMin - 1),
};

const normalizeGroups = (rule = {}) => (Array.isArray(rule.groups) ? rule.groups : [rule.groups])
  .filter(Boolean)
  .map((group) => String(group).toLowerCase());
const hasAny = (groups, candidates) => candidates.some((candidate) => groups.includes(candidate));
const classifyRule = (rule = {}) => {
  const groups = normalizeGroups(rule);
  const categories = [];
  if ((rule.mitre?.tactic?.length || 0) > 0 || (rule.mitre?.technique?.length || 0) > 0) categories.push('Threat Detection');
  if (hasAny(groups, ['syscheck', 'fim'])) categories.push('File Integrity Monitoring');
  if (groups.includes('sca')) categories.push('Security Configuration Assessment');
  if (groups.includes('vulnerability-detector')) categories.push('Vulnerability Detection');
  if (hasAny(groups, ['authentication_success', 'authentication_failed', 'authentication_failures', 'pam', 'sshd'])) categories.push('Authentication Monitoring');
  if (hasAny(groups, ['ossec', 'docker', 'rootcheck', 'agentless'])) categories.push('System & Operational Monitoring');
  if (['pci_dss', 'hipaa', 'gdpr', 'nist_800_53', 'tsc', 'cis', 'soc_2'].some((field) => (rule[field]?.length || 0) > 0)) categories.push('Compliance Context');
  return categories.length ? categories : ['Other / Unclassified'];
};

const topRules = (aggs.top_rules?.buckets || []).map((bucket) => {
  const source = bucket.sample?.hits?.hits?.[0]?._source || {};
  return {
    id: String(bucket.key),
    count: Number(bucket.doc_count || 0),
    description: source.rule?.description || 'No description',
    level: Number(source.rule?.level || 0),
    groups: source.rule?.groups || [],
    useCases: classifyRule(source.rule || {}),
  };
});

const topAgents = (aggs.top_agents?.buckets || []).map((bucket) => ({
  name: String(bucket.key),
  count: Number(bucket.doc_count || 0),
}));

const labels = {
  threat_detection: 'Threat Detection',
  file_integrity_monitoring: 'File Integrity Monitoring',
  security_configuration_assessment: 'Security Configuration Assessment',
  vulnerability_detection: 'Vulnerability Detection',
  authentication_monitoring: 'Authentication Monitoring',
  system_operational_monitoring: 'System & Operational Monitoring',
  compliance_context: 'Compliance Context',
  other_unclassified: 'Other / Unclassified',
};
const coverageBuckets = aggs.use_case_coverage?.buckets || {};
const useCaseCoverage = Object.entries(labels).map(([key, name]) => {
  const count = Number(coverageBuckets[key]?.doc_count || 0);
  return {
    key,
    name,
    count,
    percentage: total > 0 ? Number(((count / total) * 100).toFixed(1)) : 0,
  };
});

const threatMitreCount = Number(aggs.threat_mitre?.doc_count || 0);
const tactics = (aggs.threat_mitre?.tactics?.buckets || []).map((bucket) => ({
  name: String(bucket.key),
  count: Number(bucket.doc_count || 0),
}));
const techniques = (aggs.threat_mitre?.techniques?.buckets || []).map((bucket) => ({
  name: String(bucket.key),
  count: Number(bucket.doc_count || 0),
}));

const evidence = hits.map((hit) => {
  const source = hit._source || {};
  const agent = source.agent?.name || source.agent?.id || 'unassigned';
  const ruleId = String(source.rule?.id || '');
  const timestamp = source.timestamp || '';
  const location = source.location || '';
  return {
    eventId: String(hit._id || source.id || [timestamp, agent, ruleId, location].join('|')),
    timestamp,
    agent,
    ruleId,
    level: Number(source.rule?.level || 0),
    description: source.rule?.description || '',
    useCases: classifyRule(source.rule || {}),
    tactics: source.rule?.mitre?.tactic || [],
    techniques: source.rule?.mitre?.technique || [],
    location,
    decoder: source.decoder?.name || '',
    sourceIp: source.data?.srcip || source.data?.src_ip || source.srcip || '',
    destinationIp: source.data?.dstip || source.data?.dst_ip || source.dstip || '',
    user: source.data?.srcuser || source.data?.dstuser || source.data?.user || '',
  };
});

const reportMode = ['manual_report', 'weekly', 'monthly'].includes(config.runMode);
const immediateMode = ['immediate', 'immediate_test'].includes(config.runMode);
const urgentEvents = evidence.filter((event) => event.level >= config.highLevelMin);

return [{
  json: {
    runMode: config.runMode,
    periodStart: queryMeta.periodStart,
    periodEnd: queryMeta.periodEnd,
    total,
    counts,
    topRules,
    topAgents,
    useCaseCoverage,
    useCaseCoverageIsNonExclusive: true,
    threatMitreCount,
    threatMitrePercentage: total > 0 ? Number(((threatMitreCount / total) * 100).toFixed(1)) : 0,
    tactics,
    techniques,
    evidence,
    reportMode,
    immediateMode,
    urgentEvents,
    shouldContinue: reportMode || (immediateMode && urgentEvents.length > 0),
    aiContext: {
      reportingWindow: { start: queryMeta.periodStart, end: queryMeta.periodEnd },
      totalAlerts: total,
      severityCounts: counts,
      wazuhUseCaseCoverage: useCaseCoverage,
      coverageInterpretation: 'Use-case counts are non-exclusive because one Wazuh event can support multiple security contexts.',
      topRules: topRules.slice(0, 12).map(({ id, count, description, level, groups, useCases }) => ({ id, count, description, level, groups, useCases })),
      threatDetectionMitre: {
        mappedAlertCount: threatMitreCount,
        percentageOfAllAlerts: total > 0 ? Number(((threatMitreCount / total) * 100).toFixed(1)) : 0,
        tactics: tactics.slice(0, 12),
        techniques: techniques.slice(0, 12),
      },
      dataHandling: 'Only aggregate metrics, rule summaries, Wazuh use-case coverage, and MITRE context for Threat Detection are provided. Asset names and complete event records are excluded.',
    },
  },
}];

const reports = $('Build role-based deliveries').all().filter((item) => item.json.deliveryType === 'report');
return $input.all().map((item, index) => {
 if (item.binary?.reportPdf) item.binary.reportPdf.fileName = reports[index]?.json.fileName || 'wazuh-security-report.pdf';
 return item;
});

const context = $('Build deterministic security context').first().json;
const config = $('Configure alert intelligence workflow').first().json;
const profiles = $('Load enabled delivery profiles').all().map((item) => item.json);
const chainResult = $input.first().json;
const ai = chainResult.output?.output || chainResult.output || chainResult;
const counts = context.counts;

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
})[character]);
const pct = (value, total = context.total) => total > 0
  ? Math.round((Number(value || 0) / total) * 1000) / 10
  : 0;
const rows = (items, renderer, empty = 'No data available', colspan = 5) => items.length
  ? items.map(renderer).join('')
  : `<tr><td colspan="${colspan}" class="empty">${empty}</td></tr>`;
const list = (items, renderer) => items?.length
  ? `<ul class="clean-list">${items.map(renderer).join('')}</ul>`
  : '<p class="muted">No additional observation was produced.</p>';

const attention = counts.critical > 0
  ? { label: 'IMMEDIATE ATTENTION', color: '#b42318', background: '#fef3f2', border: '#fecdca' }
  : counts.high > 0
    ? { label: 'ELEVATED ATTENTION', color: '#9a6700', background: '#fff8e7', border: '#f4c95d' }
    : { label: 'STABLE ACTIVITY', color: '#067647', background: '#ecfdf3', border: '#abefc6' };
const generatedAt = new Date().toISOString();

const commonStyle = `<style>
@page{size:A4;margin:14mm}
body{margin:0;padding:0;background:#eef2f6;color:#172033;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.55}
table{border-spacing:0;border-collapse:collapse}
.shell{width:100%;max-width:760px;margin:0 auto;background:#fff}
.section{padding:0 34px 28px}
.section-title{font-size:19px;line-height:26px;font-weight:700;color:#172033;margin:0}
.section-rule{width:42px;height:4px;background:#0aa9b8;font-size:0;line-height:0;margin:10px 0 18px}
.data-table{width:100%;border:1px solid #d8e0ea;margin:0}
.data-table th{background:#f3f6f9;color:#41516a;font-size:11px;line-height:16px;text-transform:uppercase;letter-spacing:.4px;padding:10px;border:1px solid #d8e0ea;text-align:left}
.data-table td{color:#25334a;font-size:12px;line-height:17px;padding:10px;border:1px solid #d8e0ea;vertical-align:top}
.empty{color:#66758a;text-align:center}
.muted{color:#66758a}
.clean-list{margin:0;padding-left:20px;color:#25334a}
.clean-list li{padding:0 0 8px}
.page{page-break-before:always;padding-top:20px}
.footer{padding:22px 34px 30px;color:#748197;font-size:10px;line-height:15px;border-top:1px solid #e4e9f0}
@media only screen and (max-width:620px){.shell{width:100%!important}.section{padding-left:18px!important;padding-right:18px!important}.mobile-block{display:block!important;width:100%!important}.mobile-center{text-align:center!important}.hide-mobile{display:none!important}}
</style>`;

const header = (title, subtitle) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${commonStyle}</head><body><table role="presentation" width="100%" style="width:100%;background:#eef2f6"><tr><td align="center" style="padding:24px 10px"><table role="presentation" class="shell" width="760" style="width:760px;max-width:760px;background:#fff;border-top:7px solid #0aa9b8;border-radius:14px 14px 0 0"><tr><td style="background:#0f1d31;padding:32px 34px 30px"><table role="presentation" width="100%"><tr><td width="56" valign="top"><div style="width:46px;height:46px;line-height:46px;background:#0aa9b8;border-radius:12px;color:#fff;text-align:center;font-size:17px;font-weight:700">WS</div></td><td valign="top"><div style="color:#91a2b9;font-size:11px;line-height:16px;letter-spacing:1.3px;text-transform:uppercase">Wazuh Security Intelligence</div><div style="color:#fff;font-size:27px;line-height:34px;font-weight:700;padding-top:4px">${esc(title)}</div><div style="color:#c5cfdd;font-size:12px;line-height:18px;padding-top:8px">${esc(config.organizationName)} &nbsp;&bull;&nbsp; ${esc(subtitle)}</div></td><td width="178" valign="top" align="right" class="hide-mobile"><span style="display:inline-block;color:${attention.color};background:${attention.background};border:1px solid ${attention.border};border-radius:18px;padding:7px 12px;font-size:10px;line-height:14px;font-weight:700">${attention.label}</span></td></tr></table></td></tr>`;

const close = (message) => `<tr><td class="footer">${esc(message)}<br>Reporting window: ${esc(context.periodStart)} to ${esc(context.periodEnd)} &nbsp;&bull;&nbsp; Generated ${esc(generatedAt)}</td></tr></table></td></tr></table></body></html>`;

const activityHero = `<tr><td style="padding:26px 34px 20px"><table role="presentation" width="100%" style="background:#f4f7fa;border-radius:14px"><tr><td style="padding:22px 24px"><div style="color:#65758d;font-size:11px;line-height:16px;text-transform:uppercase;letter-spacing:.8px;font-weight:700">Security activity analyzed</div><div style="color:#172033;font-size:38px;line-height:44px;font-weight:700">${context.total.toLocaleString('en-US')}</div></td><td align="right" style="padding:22px 24px;color:#65758d;font-size:12px;line-height:18px">Wazuh alerts<br>across ${context.useCaseCoverage.length} security contexts</td></tr></table></td></tr>`;

const severityCell = (label, value, color, border = true) => `<td width="25%" align="center" style="width:25%;padding:18px 8px;border-right:${border ? '1px solid #dbe3ec' : '0'}"><div style="color:#65758d;font-size:11px;line-height:16px;font-weight:700;text-transform:uppercase">${label}</div><div style="color:${color};font-size:29px;line-height:36px;font-weight:700">${Number(value || 0).toLocaleString('en-US')}</div></td>`;
const severityStrip = `<tr><td style="padding:0 34px 30px"><table role="presentation" width="100%" style="border-top:1px solid #e4e9f0;border-bottom:1px solid #e4e9f0"><tr>${severityCell('Critical', counts.critical, '#b42318')}${severityCell('High', counts.high, '#d9480f')}${severityCell('Medium', counts.medium, '#c17b00')}${severityCell('Low', counts.low, '#008577', false)}</tr></table></td></tr>`;

const sectionTitle = (title) => `<div class="section-title">${esc(title)}</div><div class="section-rule">&nbsp;</div>`;
const callout = (content, tone = 'amber') => {
  const colors = tone === 'blue'
    ? { bg: '#eef4ff', border: '#6172d6', text: '#27364f' }
    : tone === 'red'
      ? { bg: '#fef3f2', border: '#d92d20', text: '#5c211d' }
      : { bg: '#fff8e7', border: '#f2b01e', text: '#543b0a' };
  return `<div style="background:${colors.bg};border-left:5px solid ${colors.border};padding:16px 18px;color:${colors.text};border-radius:0 10px 10px 0">${content}</div>`;
};

const coverageBars = context.useCaseCoverage.slice(0, 8).map((item) => {
  const width = Math.max(2, Math.min(100, Number(item.percentage || 0)));
  return `<tr><td width="34%" style="padding:7px 10px 7px 0;color:#25334a;font-size:12px">${esc(item.name)}</td><td width="54%" style="padding:7px 10px"><table role="presentation" width="100%" style="background:#e8edf3;border-radius:7px"><tr><td width="${width}%" style="width:${width}%;height:10px;background:#0aa9b8;border-radius:7px;font-size:0;line-height:0">&nbsp;</td><td style="font-size:0;line-height:0">&nbsp;</td></tr></table></td><td width="12%" align="right" style="padding:7px 0;color:#25334a;font-size:12px;font-weight:700">${item.percentage}%</td></tr>`;
}).join('');
const coverageSection = `<tr><td class="section">${sectionTitle('Wazuh use-case coverage')}<div class="muted" style="font-size:11px;margin:-10px 0 10px">Non-exclusive coverage: one alert may support multiple security contexts.</div><table role="presentation" width="100%">${coverageBars || '<tr><td class="empty">No Wazuh use-case context was identified.</td></tr>'}</table></td></tr>`;

const actionRows = rows(ai.recommendedActions || [], (action) => `<tr><td style="font-weight:700;color:#41516a;white-space:nowrap">${esc(action.priority)}</td><td>${esc(action.action)}</td><td>${esc(action.rationale)}</td></tr>`, 'No recommended action was produced.', 3);
const actionsSection = `<tr><td class="section">${sectionTitle('Priority actions')}<table class="data-table"><tr><th>Priority</th><th>Action</th><th>Rationale</th></tr>${actionRows}</table></td></tr>`;
const limitationsSection = `<tr><td class="section">${sectionTitle('Evidence limitations')}${list(ai.limitations || [], (item) => `<li>${esc(item)}</li>`)}</td></tr>`;

const executiveBody = () => `${header('Executive Security Report', 'Leadership view')}${activityHero}${severityStrip}<tr><td class="section">${sectionTitle('Executive risk snapshot')}${callout(`<strong>${pct(counts.critical + counts.high)}% of observed alerts are Critical or High.</strong> ${esc(ai.executiveSummary)}`)}</td></tr><tr><td class="section">${sectionTitle('Risk narrative')}${callout(esc(ai.riskNarrative), 'blue')}</td></tr>${coverageSection}<tr><td class="section"><table role="presentation" width="100%"><tr><td width="50%" valign="top" style="padding-right:8px"><div style="border:1px solid #d8e0ea;background:#f7f9fc;padding:16px;min-height:128px"><div style="font-size:15px;font-weight:700;margin-bottom:10px">Leadership focus</div>${list((ai.recommendedActions || []).slice(0, 3), (action) => `<li>${esc(action.action)}</li>`)}</div></td><td width="50%" valign="top" style="padding-left:8px"><div style="border:1px solid #d8e0ea;background:#f7f9fc;padding:16px;min-height:128px"><div style="font-size:15px;font-weight:700;margin-bottom:8px">MITRE visibility</div><div style="font-size:28px;line-height:34px;font-weight:700;color:#6941c6">${context.threatMitrePercentage}%</div><div class="muted" style="font-size:11px">${context.threatMitreCount.toLocaleString('en-US')} alerts include mapped Threat Detection context. Other Wazuh use cases remain reported separately.</div></div></td></tr></table></td></tr>${actionsSection}${limitationsSection}${close('Wazuh metrics remain authoritative. Gemini enriches narrative and recommendations only; analyst validation is required before response, suppression, or tuning.')}`;

const topRulesSection = `<tr><td class="section">${sectionTitle('Top Wazuh rules across all use cases')}<table class="data-table"><tr><th>Rule</th><th>Description</th><th>Level</th><th>Count</th><th>Use case(s)</th></tr>${rows(context.topRules, (rule) => `<tr><td>${esc(rule.id)}</td><td>${esc(rule.description)}</td><td>${rule.level}</td><td>${Number(rule.count || 0).toLocaleString('en-US')}</td><td>${esc(rule.useCases.join(', '))}</td></tr>`)}</table></td></tr>`;
const agentsSection = `<tr><td class="section">${sectionTitle('Most affected assets')}<table class="data-table"><tr><th>Asset / agent</th><th>Events</th></tr>${rows(context.topAgents.slice(0, 10), (agent) => `<tr><td>${esc(agent.name)}</td><td>${Number(agent.count || 0).toLocaleString('en-US')}</td></tr>`, 'No affected assets were returned.', 2)}</table></td></tr>`;
const mitreSection = `<tr><td class="section">${sectionTitle('Threat Detection — MITRE ATT&CK context')}<p class="muted" style="font-size:11px">${context.threatMitreCount.toLocaleString('en-US')} alerts (${context.threatMitrePercentage}% of all alerts) contain a Wazuh MITRE ATT&amp;CK mapping. MITRE is shown only for this Threat Detection subset; other Wazuh use cases remain represented separately.</p><table role="presentation" width="100%"><tr><td width="50%" valign="top" style="padding-right:8px"><table class="data-table"><tr><th>Tactic</th><th>Mapped alerts</th></tr>${rows(context.tactics, (item) => `<tr><td>${esc(item.name)}</td><td>${item.count}</td></tr>`, 'No tactics mapped.', 2)}</table></td><td width="50%" valign="top" style="padding-left:8px"><table class="data-table"><tr><th>Technique</th><th>Mapped alerts</th></tr>${rows(context.techniques, (item) => `<tr><td>${esc(item.name)}</td><td>${item.count}</td></tr>`, 'No techniques mapped.', 2)}</table></td></tr></table></td></tr>`;
const observationsSection = `<tr><td class="section">${sectionTitle('AI-assisted technical observations')}${callout(list(ai.technicalObservations || [], (item) => `<li>${esc(item)}</li>`), 'blue')}</td></tr>`;
const evidenceSection = `<tr><td class="section">${sectionTitle('Recent evidence sample')}<table class="data-table"><tr><th>Time</th><th>Agent</th><th>Rule</th><th>Level</th><th>Use case(s)</th><th>Description</th></tr>${rows(context.evidence, (event) => `<tr><td>${esc(event.timestamp)}</td><td>${esc(event.agent)}</td><td>${esc(event.ruleId)}</td><td>${event.level}</td><td>${esc(event.useCases.join(', '))}</td><td>${esc(event.description)}</td></tr>`, 'No recent evidence was returned.', 6)}</table></td></tr>`;

const technicalBody = (isAppendix = false) => `${isAppendix ? '<tr><td class="section page">' + sectionTitle('Technical appendix') + '</td></tr>' : header('Technical Security Report', 'SOC and engineering view')}${isAppendix ? '' : activityHero + severityStrip}${coverageSection}${topRulesSection}${mitreSection}${observationsSection}${evidenceSection}${actionsSection}${limitationsSection}`;
const technical = () => `${technicalBody()}${close('This report is evidence-oriented. Validate context before changing rules, decoders, thresholds, suppressions, or response actions.')}`;
const combined = () => `${header('Combined Security Intelligence Report', 'Leadership summary and technical evidence')}${activityHero}${severityStrip}<tr><td class="section">${sectionTitle('Executive summary')}${callout(esc(ai.executiveSummary), 'blue')}</td></tr><tr><td class="section">${sectionTitle('Risk narrative')}${callout(esc(ai.riskNarrative))}</td></tr>${actionsSection}${technicalBody(true)}${close('Wazuh supplies the evidence; Gemini enriches the narrative; n8n applies explicit routing and presentation profiles.')}`;

const immediate = (event, severity, testPrefix) => {
  const severityTheme = severity === 'critical'
    ? { color: '#b42318', background: '#fef3f2', border: '#fecdca' }
    : { color: '#d9480f', background: '#fff4ed', border: '#ffd6ae' };
  const detailRow = (label, value) => value
    ? `<tr><td width="30%" style="color:#65758d;font-size:11px;line-height:16px;text-transform:uppercase;font-weight:700;padding:10px;border-bottom:1px solid #e4e9f0">${esc(label)}</td><td style="color:#25334a;font-size:13px;line-height:19px;padding:10px;border-bottom:1px solid #e4e9f0">${esc(value)}</td></tr>`
    : '';
  const eventHeader = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${commonStyle}</head><body><table role="presentation" width="100%" style="width:100%;background:#eef2f6"><tr><td align="center" style="padding:24px 10px"><table role="presentation" class="shell" width="760" style="width:760px;max-width:760px;background:#fff;border-top:7px solid ${severityTheme.color};border-radius:14px 14px 0 0"><tr><td style="background:#0f1d31;padding:32px 34px 30px"><table role="presentation" width="100%"><tr><td width="56" valign="top"><div style="width:46px;height:46px;line-height:46px;background:${severityTheme.color};border-radius:12px;color:#fff;text-align:center;font-size:17px;font-weight:700">WS</div></td><td valign="top"><div style="color:#91a2b9;font-size:11px;line-height:16px;letter-spacing:1.3px;text-transform:uppercase">Wazuh Security Alert</div><div style="color:#fff;font-size:25px;line-height:32px;font-weight:700;padding-top:4px">${esc(event.description || `Rule ${event.ruleId}`)}</div><div style="color:#c5cfdd;font-size:12px;line-height:18px;padding-top:8px">${esc(config.organizationName)} &nbsp;&bull;&nbsp; Individual event notification</div></td><td width="120" valign="top" align="right" class="hide-mobile"><span style="display:inline-block;color:${severityTheme.color};background:${severityTheme.background};border:1px solid ${severityTheme.border};border-radius:18px;padding:7px 12px;font-size:10px;line-height:14px;font-weight:700">${testPrefix}${severity.toUpperCase()}</span></td></tr></table></td></tr>`;
  const details = [
    detailRow('Event time', event.timestamp),
    detailRow('Wazuh event ID', event.eventId),
    detailRow('Agent / asset', event.agent),
    detailRow('Rule', event.ruleId),
    detailRow('Rule level', event.level),
    detailRow('Description', event.description),
    detailRow('Location', event.location),
    detailRow('Decoder', event.decoder),
    detailRow('Source IP', event.sourceIp),
    detailRow('Destination IP', event.destinationIp),
    detailRow('User', event.user),
    detailRow('Wazuh use case(s)', event.useCases?.join(', ')),
    detailRow('MITRE tactic(s)', event.tactics?.join(', ')),
    detailRow('MITRE technique(s)', event.techniques?.join(', ')),
  ].join('');
  const nextSteps = severity === 'critical'
    ? ['Validate the event and affected asset immediately.', 'Correlate the source, user, and related events in Wazuh.', 'Escalate through the incident-response process if malicious activity is confirmed.']
    : ['Validate the event and affected asset according to the SOC triage process.', 'Review related Wazuh events for the same source, user, rule, or asset.', 'Escalate if corroborating evidence increases the assessed risk.'];
  const eventFooter = `<tr><td class="footer">This message contains one Critical or High Wazuh event. Validate the evidence before containment, suppression, tuning, or response.<br>Event timestamp: ${esc(event.timestamp || 'Unavailable')} &nbsp;&bull;&nbsp; Event ID: ${esc(event.eventId)}</td></tr></table></td></tr></table></body></html>`;
  return `${eventHeader}<tr><td style="padding:26px 34px 22px"><div style="background:${severityTheme.background};border-left:5px solid ${severityTheme.color};padding:16px 18px;color:#25334a;border-radius:0 10px 10px 0"><strong>${severity.toUpperCase()} Wazuh event detected.</strong><br>This notification represents one specific alert, not an aggregate or reporting-period summary.</div></td></tr><tr><td class="section">${sectionTitle('Alert evidence')}<table role="presentation" width="100%" style="border:1px solid #d8e0ea">${details}</table></td></tr><tr><td class="section">${sectionTitle('Recommended triage')}${list(nextSteps, (item) => `<li>${esc(item)}</li>`)}</td></tr>${eventFooter}`;
};

const deliveries = [];
if (context.reportMode) {
  const eligibleProfiles = profiles.filter((profile) => {
    const receivesReports = profile.receiveReports ?? profile.receivePdfReports;
    const correctCadence = config.runMode === 'manual_report' || profile.reportCadence === config.runMode;
    return profile.enabled && receivesReports && correctCadence;
  });
  for (const profile of eligibleProfiles) {
    const audience = String(profile.audienceProfile || 'combined').toLowerCase();
    const html = audience === 'executive' ? executiveBody() : audience === 'technical' ? technical() : combined();
    deliveries.push({ json: {
      deliveryKey: `${config.organizationKey}|${profile.profileKey}|report|${context.periodEnd}`,
      runId: $execution.id || 'manual',
      organizationKey: config.organizationKey,
      recipientEmail: profile.recipientEmail,
      recipientName: profile.recipientName || '',
      deliveryType: 'report',
      audienceProfile: audience,
      severity: '',
      periodStart: context.periodStart,
      periodEnd: context.periodEnd,
      subject: `[${config.organizationName}] ${audience.charAt(0).toUpperCase() + audience.slice(1)} Wazuh Security Report`,
      emailHtml: html,
      reportHtml: html,
      fileName: `wazuh-${audience}-security-report.pdf`,
    } });
  }
}

if (context.immediateMode && context.urgentEvents?.length > 0) {
  const urgentEvents = config.runMode === 'immediate_test'
    ? context.urgentEvents.slice(0, 1)
    : context.urgentEvents;
  for (const profile of profiles.filter((item) => item.enabled && item.receiveImmediateAlerts)) {
    let allowed = [];
    try { allowed = JSON.parse(profile.immediateSeverities_object || '[]'); } catch {}
    for (const event of urgentEvents) {
      const severity = event.level >= config.criticalLevelMin ? 'critical' : 'high';
      if (!allowed.includes(severity)) continue;
      const testPrefix = config.runMode === 'immediate_test' ? '[TEST] ' : '';
      deliveries.push({ json: {
        deliveryKey: `${config.organizationKey}|${profile.profileKey}|alert|${event.eventId}`,
        runId: $execution.id || 'manual',
        organizationKey: config.organizationKey,
        recipientEmail: profile.recipientEmail,
        recipientName: profile.recipientName || '',
        deliveryType: 'immediate_alert',
        audienceProfile: profile.audienceProfile || 'technical',
        severity,
        eventId: event.eventId,
        ruleId: event.ruleId,
        agent: event.agent,
        periodStart: event.timestamp || context.periodStart,
        periodEnd: event.timestamp || context.periodEnd,
        subject: `${testPrefix}[${severity.toUpperCase()}] Wazuh rule ${event.ruleId || 'unknown'} on ${event.agent || 'unassigned'}`,
        emailHtml: immediate(event, severity, testPrefix),
        reportHtml: '',
        fileName: '',
      } });
    }
  }
}

return deliveries;
